import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 101, E: 33.33 }
let server, base

before(async () => {
  server = createServer(createApp({ pricing: { priceOf: async (sku) => prices[sku] } }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

async function totalFor(items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  const order = await res.json()
  const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
  assert.equal(fetched.total, order.total)
  return order.total
}

test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('no discount at exactly 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount applies strictly above 100', async () => {
  // 101 * 0.9 = 90.9, floored
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 90)
  assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900)
})

test('total is floored to whole euros (cents dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 1 }]), 25)
  assert.equal(await totalFor([{ sku: 'E', qty: 3 }]), 99) // 99.99 -> 99
})

test('floating point: fractional prices', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 0)
})

test('rejects empty or missing items', async () => {
  for (const body of [{}, { items: [] }]) {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify(body) })
    assert.equal(res.status, 400)
  }
})
EOF
